/* Optional daily shortlist; each account owns its preference and task selection. */
(()=>{'use strict';if(!document.body.classList.contains('shared-app'))return;
const q=s=>document.querySelector(s),day=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Tehran',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
const prefs=()=>window.SamandisPreferences;
function eligible(){return tasks.filter(t=>own(t)||collaborating(t))}
function dailyList(list,today){const localDay=value=>value?new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Tehran',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date(value)):'';return list.filter(t=>{if(t.status==='done')return localDay(t.approved_at||t.submitted_at)===today;return t.due?t.due<=today:!t.starts_on||t.starts_on<=today}).sort((a,b)=>(a.status==='done')-(b.status==='done')||(a.due||'9999').localeCompare(b.due||'9999'))}
async function save(key,value){try{await prefs().set(key,value);sync();return true}catch(e){message('ذخیره نشد؛ دوباره تلاش کنید.');return false}}
let expanded=true;
function sync(){const me=typeof mine==='function'&&mine(),enabled=!!prefs()?.get('today-plan-enabled',false);const menu=q('#accountMorePanel');let toggle=q('#todayPlanToggle');if(menu&&!toggle){toggle=document.createElement('button');toggle.type='button';toggle.id='todayPlanToggle';toggle.className='account-settings-link';toggle.onclick=async()=>{await save('today-plan-enabled',!prefs().get('today-plan-enabled',false))};menu.append(toggle)}if(toggle){toggle.hidden=!me;toggle.textContent=enabled?'حذف Daily To Do List':'افزودن Daily To Do List';toggle.setAttribute('aria-pressed',String(enabled))}
let box=q('#todayPlan');if(!me||!enabled||window.SAMANDIS_PERSONAL_MODE){box?.remove();return}if(!box){box=document.createElement('details');box.id='todayPlan';box.open=expanded;box.addEventListener('toggle',()=>expanded=box.open);q('#deskNav')?.after(box)}const list=dailyList(eligible(),day());box.innerHTML='<summary>Daily To Do List</summary><div class="today-plan-list">'+list.map(t=>'<button type="button" data-today-task="'+esc(t.id)+'"><span class="today-plan-dot '+(t.status==='done'?'done':'')+'">'+(t.status==='done'?'✓':'')+'</span><span>'+esc(t.title)+'</span></button>').join('')+'</div><p class="today-plan-note">'+(list.length?'کارهای امروز، عقب‌افتاده و بدون مهلت':'برای امروز کاری ندارید.')+'</p>';box.querySelectorAll('[data-today-task]').forEach(b=>b.onclick=()=>detail(b.dataset.todayTask))}
const old=render;render=function(...args){const r=old(...args);sync();return r};document.addEventListener('samandis-preferences-loaded',sync);setInterval(sync,60000);sync();
})();
